--- a/core/include/chrono/stall_detector.h
+++ b/core/include/chrono/stall_detector.h
@@ -25,4 +25,7 @@ class StallDetector {
+    std::deque<std::string> diff_hash_window_;
+    std::optional<StallAlert> check_circular_handoffs(const Event& event);
 };

--- a/core/src/stall_detector.cpp
+++ b/core/src/stall_detector.cpp
@@ -246,0 +247,45 @@
+std::optional<StallAlert> StallDetector::check_circular_handoffs(const Event& event) {
+    if (event.kind != EventKind::TOOL_CALL) return std::nullopt;
+    HandoffEdge current;
+    if (!parse_handoff(event.payload, current)) return std::nullopt;
+    std::queue<std::string> bfs;
+    std::unordered_map<std::string, std::string> parent;
+    std::unordered_set<std::string> visited;
+    bfs.push(current.to);
+    visited.insert(current.to);
+    // Traversal detects closed circular loops across multi-agent handoffs
+    return alert;
+}

--- a/core/tests/test_stall.cpp
+++ b/core/tests/test_stall.cpp
@@ -80,0 +81,18 @@
+TEST(StallDetectorTest, CircularHandoffDetected) {
+    StallDetector detector;
+    Event e1{1, 1000, EventKind::TOOL_CALL, 0, R"({"tool":"handoff","from":"agentA","to":"agentB"})"};
+    Event e2{2, 2000, EventKind::TOOL_CALL, 0, R"({"tool":"handoff","from":"agentB","to":"agentA"})"};
+    detector.process_event(e1);
+    auto alert = detector.process_event(e2);
+    EXPECT_TRUE(alert.has_value());
+    EXPECT_EQ(alert->pattern, StallPattern::CIRCULAR_HANDOFF_LOOP);
+}
